        local it = F.cheapest(function(v)
            if not (A and A.isAio and A.isAio(v)) then return false end
            local cs = D.Net.state.parts.case and C.get(D.Net.state.parts.case.item)
            if not cs then return false end
            local okF, f = pcall(A.fits, cs, v)
            return okF and f == true
        end)
        if not it then return end
        plan = { item = it.id, n = 1 } order[it.id] = 1
    end
    if not plan then return end
    local need = {}
    for id, n in pairs(order) do
        local inv = tonumber((st.inventory or {})[id]) or 0
        if inv < n then need[id] = n - inv end
    end
    if next(need) then
        local r = M.inv("SupplyRequest", "order", { items = need })
        LOG("ordered", plan.item, plan.n, type(r) == "table" and r.ok, type(r) == "table" and r.reason)
        if not F.waitParts(order, 110) then LOG("parts late", plan.item) return end
    end
    local cat = C.get(plan.item).category
    if up.kind == "ram" or up.kind == "gpu" or up.kind == "aio" then
        for slot, pt in pairs(D.Net.state.parts) do
            local d = C.get(pt.item)
            if d and (d.category == cat or (up.kind == "aio" and d.category == "Cooler")) then F.unscrew(slot) end
        end
        if up.kind == "aio" then M.req("wipe", {}) M.req("paste", { amount = 0.6 }) end
    end
    for _ = 1, plan.n do F.fitItem(plan.item) end
    LOG("upgrade", up.kind, plan.item, plan.n, RJ.upgradeHave(D.Net.state, up.kind), up.want)
end
F.FIX = { upgrade = F.fixUpgrade, cable = F.fixCables, software = F.fixSoftware, paste = F.fixPaste, part = F.fixParts }
