function F.deliver()
    F.panels(true)
    local r = M.rr("offBench")
    if not r.ok then
        M.req("power", { on = false })
        for k in pairs(D.Net.state.peripherals or {}) do M.req("unplug", { key = k }) end
        r = M.rr("offBench")
    end
    if not r.ok then LOG("offBench fail", r.reason) return false end
    task.wait(0.3)
    local sh = M.shop()
    local dp = sh and sh:FindFirstChild("DeskPrompt", true)
    if dp then
        for _ = 1, 4 do
            M.prompt(dp)
            task.wait(0.5)
            if not lp:GetAttribute("Carrying") then break end
        end
    end
    return not lp:GetAttribute("Carrying")
