function F.collectDone()
    for _, j in pairs(F.jobs or {}) do
        if type(j) == "table" and j.fixed and j.stage == "station" and not F.skipJob["c" .. tostring(j.id)] then
            F.skipJob["c" .. tostring(j.id)] = true
            local pc = F.pcModel(j.id)
