            if pp and pp.Enabled then
                for _ = 1, 4 do M.prompt(pp) task.wait(0.4) if lp:GetAttribute("Carrying") then break end end
                if lp:GetAttribute("Carrying") then
                    local ok = F.toDesk()
                    LOG("collected from station", j.id, ok)
                    if ok then return true end
                end
            end
        end
    end
    return false
end
function F.pickJob()
    local best, bs
    for _, j in pairs(F.jobs or {}) do
        if type(j) == "table" and (j.stage == "waiting" or j.stage == "counter" or j.stage == "accepted") and not j.fixed then
            if j.stage ~= "waiting" or F.canDo(j) or F.techCan(j) then
                local s = (tonumber(j.pay) or 0) * (j.vip and 12 or 1)
                if not bs or s > bs then best, bs = j, s end
            end
        end
    end
    return best
end
F.techAt = 0
F.techStars = 0
function F.techInfo()
    if os.clock() - F.techAt < 4 then return F.techStars end
