    local a = M.inv("StaffRequest", "state")
    local best = 0
    F.techTotal = 0
    for _, p in ipairs(type(a) == "table" and a.result and a.result.people or {}) do
        if p.role == "tech" then F.techTotal += 1 end
        local busy = tostring(p.status or ""):find("^Fixing") or tostring(p.status or ""):find("^Building")
        if p.role == "tech" and not busy then best = math.max(best, tonumber(p.stars) or 1) end
    end
    F.techStars = best
    return best
end
