F.skipJob = {}
F.benchTries = {}
function F.repairOne()
    if not on("f_repair") then return false end
    if lp:GetAttribute("Carrying") then
        local st = D.Net and D.Net.state
        if not (st and st.job) then M.rr("toBench") end
    end
    local st = D.Net and D.Net.state
    if st and st.job then return F.workBench() end
    local j = F.pickJob()
    if not j or F.skipJob[j.id] then return false end
    if j.stage == "waiting" or j.stage == "counter" then
        local r = M.rr("accept", { id = j.id })
        LOG("accept", j.id, j.name, j.short, r.ok, r.reason)
        if not r.ok then F.skipJob[j.id] = true return false end
    end
    S.task = __T["Getting "] .. tostring(j.name) .. __T["'s PC"] S.taskAt = os.clock()
    local t0 = os.clock()
    local pc, pp
    while RUNNING and os.clock() - t0 < 30 do
        pc = F.pcModel(j.id)
        pp = pc and pc:FindFirstChild("PickUpPrompt", true)
        if pp and pp.Enabled then break end
        task.wait(0.4)
    end
    if not (pp and pp.Enabled) then return false end
    for _ = 1, 4 do M.prompt(pp) task.wait(0.4) if lp:GetAttribute("Carrying") then break end end
    if not lp:GetAttribute("Carrying") then F.skipJob[j.id] = true return false end
    local ks = F.kindsFor(j) or {}
    for k in pairs(ks) do
        if F.STATION[k] and F.hasStation(k) and lp:GetAttribute("Carrying") then
            S.task = __T["Station: "] .. tostring(j.short) S.taskAt = os.clock()
            local okS, fixedS = F.stationRun(k, j.id)
            if okS and fixedS and lp:GetAttribute("Carrying") then
                if F.toDesk() then LOG("station delivered", j.id) return true end
            end
        end
    end
    if not F.canDo(j) then
        local hp
        for _ = 1, 20 do hp = F.handPrompt() if hp then break end task.wait(0.5) end
        if hp then
            for _ = 1, 4 do M.prompt(hp) task.wait(0.5) if not lp:GetAttribute("Carrying") then break end end
            LOG("handed to tech", j.id, j.short, not lp:GetAttribute("Carrying"))
            if not lp:GetAttribute("Carrying") then S.handed = (S.handed or 0) + 1 return true end
        end
    end
    local r = M.rr("toBench")
    LOG("toBench", j.id, r.ok, r.reason)
    task.wait(0.3)
    return F.workBench()
end
function F.stationRun(kind, jobId)
    local sh = M.shop()
    local stn = sh and sh.Placed:FindFirstChild(F.STATION[kind] or "")
    local sp = stn and stn:FindFirstChild("StationPrompt", true)
    if not sp then return false end
    F.station = nil
    for _ = 1, 4 do M.prompt(sp) task.wait(0.6) if F.station or not lp:GetAttribute("Carrying") then break end end
    local t0 = os.clock()
    while not F.station and os.clock() - t0 < 8 do
        task.wait(0.8)
        if not F.station and sp.Enabled then M.prompt(sp) end
    end
    local info = F.station
    if not info then LOG("station no event", kind) return false end
    task.wait(0.4)
    local args = { id = info.id }
    if info.kind == "mod" and type(info.mod) == "table" then
        args.paint = {}
        for k, v in pairs(info.mod) do args.paint[k] = v end
    end
    local r = M.rr("stationDone", args)
    local tS = os.clock()
    while not r.ok and tostring(r.reason or ""):find("fast") and os.clock() - tS < 30 do
        S.task = __T["Station working ("] .. tostring(info.kind) .. ")" S.taskAt = os.clock()
        task.wait(2)
        r = M.rr("stationDone", args)
    end
    if not r.ok and args.paint then
        for _, v in pairs(args.paint) do if type(v) == "string" then M.inv("ShopRequest", "buyPaint", { id = v }) end end
        r = M.rr("stationDone", args)
    end
    LOG("stationDone", kind, info.id, r.ok, r.reason, r.result and r.result.fixed)
    task.wait(0.5)
    local pc = F.pcModel(jobId)
    local pp = pc and pc:FindFirstChild("PickUpPrompt", true)
    for _ = 1, 10 do
        if pp and pp.Enabled then break end
        task.wait(0.4)
        pc = F.pcModel(jobId) pp = pc and pc:FindFirstChild("PickUpPrompt", true)
    end
    if pp then for _ = 1, 4 do M.prompt(pp) task.wait(0.4) if lp:GetAttribute("Carrying") then break end end end
    return r.ok, r.result and r.result.fixed
end
function F.toDesk()
    local sh = M.shop()
