function F.workBench()
    local st = D.Net and D.Net.state
    if not (st and st.job) then return false end
    F.restore = {}
    local job = st.job
    if (F.benchTries[job.id] or 0) >= 2 then
        S.task = __T["Stuck on "] .. tostring(job.name) .. __T["'s PC"] S.taskAt = os.clock()
        task.wait(2)
        return false
    end
    F.benchTries[job.id] = (F.benchTries[job.id] or 0) + 1
    local kind = F.kindOf(job.fault)
    S.task = __T["Fixing "] .. tostring(job.name) .. " · " .. tostring(job.short) S.taskAt = os.clock()
    local isCon = job.console or (D.Consoles and D.Consoles.isConsole and select(2, pcall(D.Consoles.isConsole, st)))
    if isCon then
        local need = D.Consoles and D.Consoles.needs and select(2, pcall(D.Consoles.needs, st))
        if type(need) == "string" and (tonumber((st.inventory or {})[need]) or 0) < 1 then
            local o = M.inv("SupplyRequest", "order", { items = { [need] = 1 } })
            LOG("ordered console part", need, type(o) == "table" and o.ok, type(o) == "table" and o.reason)
            F.waitParts({ [need] = 1 }, 110)
        end
        local r = M.rr("consoleFixed")
        LOG("consoleFixed", job.id, need, r.ok, r.reason)
    else
        local fn = F.FIX[kind or ""]
        if fn then pcall(fn) end
        if kind ~= "cable" then pcall(F.fixCables) end
    end
    local ok, why = F.isFixed()
    pcall(F.restoreAll)
    pcall(F.fixCables)
    ok, why = F.isFixed()
    for _ = 1, 3 do
        if ok then break end
        local w = tostring(why):lower()
        local fx = (w:find("asked for") and F.fixUpgrade) or (w:find("still air cooled") and F.fixUpgrade) or (w:find("missing a part") and F.fillMissing) or (w:find("paste") and F.fixPaste) or (w:find("virus") and F.fixSoftware) or (w:find("broken part") and F.fixParts) or ((w:find("cable") or w:find("start") or w:find("plug")) and F.fixCables) or nil
        if not fx then break end
        pcall(fx)
        pcall(F.fixCables)
        ok, why = F.isFixed()
    end
    LOG("fixed?", job.id, job.fault, ok, why)
    local need = not ok and (tostring(why):find("dust%-out") and "dirt" or (tostring(why):find("repair station") and "repair" or nil))
    if need and F.hasStation(need) then
        F.panels(true)
        local off = M.rr("offBench")
        if not off.ok then M.req("power", { on = false }) for k in pairs(D.Net.state.peripherals or {}) do M.req("unplug", { key = k }) end off = M.rr("offBench") end
        if off.ok then
            F.stationRun(need, job.id)
            if lp:GetAttribute("Carrying") then M.rr("toBench") task.wait(0.4) end
            ok, why = F.isFixed()
            LOG("after station", job.id, ok, why)
        end
    end
    if not ok then
        S.failed += 1
        F.skipJob[job.id] = true
        S.task = __T["Gave back: "] .. tostring(why) S.taskAt = os.clock()
        local c = M.rr("cancel", { id = job.id })
        LOG("cancel", job.id, job.fault, why, c.ok)
        return false
    end
    F.deliver()
    S.fixed += 1
    F.benchTries[job.id] = nil
    return true
end
