function F.placeItem(id, floorPref, shopOnly)
    local SR, SC = D.ShopRules, D.ShopCatalog
    local sh = M.shop()
    local it = SC and SC.ById and SC.ById[id]
    if not (SR and sh and it) then return false, "no data" end
    if M.cash() - M.reserve() < (tonumber(it.price) or 0) then return false, "cash" end
    local rooms = SR.roomsFor(sh) or {}
    table.sort(rooms, function(a, b)
        local fa = floorPref and (a.floor == floorPref and 0 or 1) or 0
        local fb = floorPref and (b.floor == floorPref and 0 or 1) or 0
        if fa ~= fb then return fa < fb end
        return (a.floor or 1) > (b.floor or 1)
    end)
    local tries = 0
    for _, room in ipairs(rooms) do
        if (shopOnly and room.name == "Shop") or (not shopOnly and (room.name ~= "Shop" or not floorPref)) then
            local fm = PB and PB:FindFirstChild("Furniture") and PB.Furniture:FindFirstChild(id)
            local mount = tostring(fm and fm:GetAttribute("Mount") or "")
            local mn, mx = room.box.min, room.box.max
            local spots = {}
            if mount == "wall" then
                for _, y in ipairs({ mn.Y + 5, mn.Y + 6.5, mn.Y + 3.5 }) do
                    for x = mn.X + 2, mx.X - 2, 2.5 do
                        spots[#spots + 1] = { x, y, mn.Z + 0.3, 0 } spots[#spots + 1] = { x, y, mx.Z - 0.3, math.pi }
                    end
                    for z = mn.Z + 2, mx.Z - 2, 2.5 do
                        spots[#spots + 1] = { mn.X + 0.3, y, z, -math.pi / 2 } spots[#spots + 1] = { mx.X - 0.3, y, z, math.pi / 2 }
                    end
                end
            else
                local y = mount == "ceiling" and mx.Y or mn.Y
                for _, yaw in ipairs({ 0, math.pi / 2, math.pi, -math.pi / 2 }) do
                    for x = mn.X + 1.5, mx.X - 1.5, 2.5 do
                        for z = mn.Z + 1.5, mx.Z - 1.5, 2.5 do spots[#spots + 1] = { x, y, z, yaw } end
                    end
                end
            end
            for _, sp in ipairs(spots) do
                do
                    do
                        local x, y, z, yaw = sp[1], sp[2], sp[3], sp[4]
                        tries += 1
                        if tries > 400 then return false, "no spot" end
                        local r = M.inv("ShopRequest", "buy", { id = id, x = x, y = y, z = z, yaw = yaw })
                        if type(r) == "table" and r.ok then LOG("placed", id, room.name, tries) return true end
                        local why = type(r) == "table" and tostring(r.reason or "") or ""
                        if why:find("tin") or why:find("afford") or why:find("cash") or why:find("[Mm]ost") or why:find("limit") then return false, why end
                    end
                end
            end
        end
    end
    return false, "no spot"
end
