F.surfTier = 0
function F.surfaces(ln)
    local SC = D.ShopCatalog
    if not (SC and SC.Surfaces and SC.Finishes) then return false end
    local byKind = {}
    for _, f in ipairs(SC.Finishes) do byKind[f.kind] = byKind[f.kind] or {} table.insert(byKind[f.kind], f) end
    for _, list in pairs(byKind) do table.sort(list, function(a, b) return (a.price or 0) < (b.price or 0) end) end
    F.surfTier += 1
    local did = false
    for key, sf in pairs(SC.Surfaces) do
        local list = byKind[sf.kind] or {}
        local f = list[math.min(F.surfTier, #list)]
        if f and M.cash() - M.reserve() >= (f.price or 0) * 4 then
            local r = M.inv("ShopRequest", "surface", { surface = key, finish = f.id })
            if type(r) == "table" and r.ok then did = true end
        end
    end
    LOG("surfaces tier", F.surfTier, did)
    return did
end
function F.decor()
    if not on("p_decor") or os.clock() - F.decorAt < 6 then return end
    F.decorAt = os.clock()
    local SA, SC = D.ShopAppeal, D.ShopCatalog
    if not (SA and SA.Items and SC and SC.ById) then return end
    local sh = F.sheet()
    local open = {}
    for _, ln in ipairs(sh.lines or {}) do
        if type(ln) == "table" and ln.id and (tonumber(ln.points) or 0) < (tonumber(ln.cap) or 0) then open[ln.id] = ln end
    end
    if open.surfaces and F.surfTier < 6 then F.surfaces(open.surfaces) return end
    local best, bv
    for id, v in pairs(SA.Items) do
        local it = SC.ById[id]
        local ln = open[v.group or ""]
        if it and ln and not F.noGain[id] and (tonumber(it.price) or 0) > 0 then
            local gain = math.min(tonumber(v.points) or 0, (tonumber(ln.cap) or 0) - (tonumber(ln.points) or 0))
            local val = gain / it.price
            if gain > 0 and M.cash() - M.reserve() >= it.price and (not bv or val > bv) then best, bv = { id = id, grp = v.group, before = ln.points }, val end
        end
    end
    if not best then return end
    local okP, why = F.placeItem(best.id, nil, true)
    LOG("decor", best.id, okP, why)
    if okP then
        S.decor = (S.decor or 0) + 1
        task.wait(1.5)
        for _, ln in ipairs(F.sheet().lines or {}) do
            if ln.id == best.grp and (tonumber(ln.points) or 0) <= (tonumber(best.before) or 0) then F.noGain[best.id] = true end
        end
    elseif why == "no spot" then F.noGain[best.id] = true end
end
