F.progAt = 0
function F.progress()
    if os.clock() - F.progAt < 5 then return end
    F.progAt = os.clock()
    local spare = M.cash() - M.reserve()
    if on("p_floors") then
        local t = M.inv("TowerRequest", "state")
        local st = type(t) == "table" and t.result
        if st and (tonumber(st.floors) or 1) < (tonumber(st.max) or 99) and tonumber(st.nextCost) and spare >= st.nextCost then
            local r = M.inv("TowerRequest", "build")
            if type(r) == "table" and r.ok then S.floors += 1 LOG("floor built", st.floors + 1, st.nextCost) spare -= st.nextCost end
        end
        local ss = st and st.benchRoom and on("p_benches") and M.inv("StaffRequest", "state")
        local full = type(ss) == "table" and ss.result and (tonumber(ss.result.benches) or 0) >= (tonumber(ss.result.benchMax) or 0)
        if st and st.benchRoom and type(st.benchRoom.next) == "table" and on("p_benches") and full then
            local c = tonumber(st.benchRoom.next.cost or st.benchRoom.next.price)
            if c and spare >= c then
                local r = M.inv("TowerRequest", "benches")
                if type(r) == "table" and r.ok then S.buys += 1 LOG("bench room", c) spare -= c end
            end
        end
    end
    if on("p_staff") then
        local a = M.inv("StaffRequest", "state")
        local st = type(a) == "table" and a.result
        for _, role in ipairs(st and st.hire or {}) do
            if role.role == "tech" and role.full == "nobench" and on("p_benchplace") and (tonumber(st.benches) or 0) < (tonumber(st.benchMax) or 0) then
                local okP, why = F.placeItem("staff_bench", nil)
                LOG("staff bench", okP, why)
                if okP then S.buys += 1 end
            end
            local want = (role.role == "tech") or (role.role == "runner" and on("p_runner")) or (role.role == "greeter" and on("p_greeter"))
            if want and not role.locked and (tonumber(role.have) or 0) < (tonumber(role.most) or 0) then
                local best
                for _, ap in ipairs(role.applicants or {}) do
                    local cost = tonumber(ap.hire) or 0
                    if cost <= spare then
                        local sc = (tonumber(ap.stars) or 1) * 10 + ((ap.trait == "quick") and 2 or (ap.trait == "steady" and 1 or 0))
                        if not best or sc > best.sc then best = { ap = ap, sc = sc, cost = cost } end
                    end
                end
                if best then
                    local r = M.inv("StaffRequest", "hire", { role = role.role, index = best.ap.index, name = best.ap.name })
                    if type(r) == "table" and r.ok then S.hires += 1 spare -= best.cost LOG("hired", role.role, best.ap.name, best.ap.stars) end
                end
            end
        end
    end
    if on("p_rebirth") then
        local RB = D.Rebirth
        local okR = RB and RB.can and select(1, pcall(RB.can, lp))
        local a = M.inv("RebirthRequest", "arm")
        if type(a) == "table" and a.ok and a.ticket then
            local r = M.inv("RebirthRequest", "confirm", { ticket = a.ticket })
            if type(r) == "table" and r.ok then S.rebirths += 1 LOG("rebirth") end
        end
    end
end
F.ctAt = 0
F.ctSkip = {}
function F.contractStep()
    if not on("f_contracts") then return false end
    if lp:GetAttribute("Carrying") or (D.Net and D.Net.state and D.Net.state.job) then return false end
    if os.clock() - F.ctAt < 2 then return false end
    F.ctAt = os.clock()
    local c = M.inv("ContractRequest", "state")
    local st = type(c) == "table" and c.result
    if not st then return false end
    local active = st.active or {}
    if next(active) == nil then
        local best, bv
        for _, of in pairs(st.offers or {}) do
            local all = true
            for _, u in pairs(of.units or {}) do
                if u.bench then
                    if not F.canDo({ short = u.label }) then all = false end
                elseif F.techCount() < 1 then all = false end
            end
            local v = (tonumber(of.pay) or 0) + (tonumber(of.bonus) or 0)
            if all and (not bv or v > bv) then best, bv = of, v end
        end
        if best and (tonumber(st.slots) or 0) > 0 then
            local r = M.inv("ContractRequest", "accept", { id = best.id })
            LOG("contract accept", best.name, bv, type(r) == "table" and r.ok)
            return type(r) == "table" and r.ok
        end
        return false
    end
    for _, ct in pairs(active) do
        for ui, u in pairs(ct.units or {}) do
            local key = tostring(ct.id) .. ":" .. tostring(ui)
            if u.status == "waiting" and u.bench and not F.ctSkip[key] then
                local r = M.inv("ContractRequest", "work", { id = ct.id, unit = ui })
                LOG("contract work", ct.name, ui, u.label, type(r) == "table" and r.ok, type(r) == "table" and r.reason)
                if type(r) == "table" and r.ok then
                    task.wait(0.5)
                    S.task = __T["Contract: "] .. tostring(ct.name) S.taskAt = os.clock()
                    if not F.workBench() then F.ctSkip[key] = true end
                    return true
                end
                F.ctSkip[key] = true
            end
        end
    end
    return false
end
function F.mainLoop()
    while RUNNING do
        local ok, err = pcall(function()
            if os.clock() < (F.pauseUntil or 0) or not M.alive() then task.wait(0.4) return end
            F.skipTutorial()
            F.openShop()
            F.talk()
            F.decline()
            if F.unpack() then return end
            if on("f_repair") and F.collectDone() then return end
            if F.repairOne() then return end
            if not F.contractStep() then task.wait(0.6) end
        end)
        if not ok then LOG("loop err", err) task.wait(0.5) end
        task.wait(0.1)
    end
end
function F.slowLoop()
    while RUNNING do
        pcall(F.rewards)
        pcall(F.progress)
        pcall(F.decor)
        pcall(F.stations)
        if os.clock() - (F.jobsAt or 0) > 15 then F.jobsAt = os.clock() pcall(M.rr, "jobs") end
        if not (D.Net and D.Rules and D.RepairJobs) then pcall(M.load) end
        task.wait(3)
    end
end
function F.antiPause(v)
    if F.pauseConn then pcall(function() F.pauseConn:Disconnect() end) F.pauseConn = nil end
    if not v then return end
    pcall(function()
        local rg = game:GetService("CoreGui"):FindFirstChild("RobloxGui")
        if not rg then return end
        local np = rg:FindFirstChild("CoreScripts/NetworkPause")
        if np then np:Destroy() end
        F.pauseConn = rg.ChildAdded:Connect(function(c)
            if c.Name == "CoreScripts/NetworkPause" then task.defer(function() pcall(function() c:Destroy() end) end) end
        end)
    end)
end
